    #[cfg(unix)]
    fn proxy_completion_http_caller_runtime_probe(cancel: bool) {
        use std::future::Future;
        use std::sync::atomic::{AtomicBool, Ordering};
        use std::task::Poll;
        let runtime = asupersync::runtime::RuntimeBuilder::current_thread()
            .with_reactor(asupersync::runtime::reactor::create_reactor().unwrap())
            .build()
            .unwrap();
        for resource in [false, true] {
            let listener = TcpListener::bind("127.0.0.1:0").unwrap();
            listener.set_nonblocking(true).unwrap();
            let address = listener.local_addr().unwrap();
            let target = format!("http-completion-{}", address.port());
            let peer_target = target.clone();
            let received = Arc::new(AtomicBool::new(false));
            let peer_received = Arc::clone(&received);
            let (release, released) = std::sync::mpsc::sync_channel(1);
            let peer = thread::spawn(move || {
                let accept = || {
                    let deadline = Instant::now() + Duration::from_secs(10);
                    loop {
                        match listener.accept() {
                            Ok((stream, _)) => {
                                stream
                                    .set_read_timeout(Some(Duration::from_secs(10)))
                                    .unwrap();
                                stream
                                    .set_write_timeout(Some(Duration::from_secs(10)))
                                    .unwrap();
                                return stream;
                            }
                            Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                                assert!(
                                    Instant::now() < deadline,
                                    "completion peer accept is bounded"
                                );
                                thread::sleep(Duration::from_millis(1));
                            }
                            Err(error) => panic!("completion peer accept: {error}"),
                        }
                    }
                };
                let mut discovery = accept();
                let request: serde_json::Value =
                    serde_json::from_slice(&read_http_request(&mut discovery).body).unwrap();
                assert_eq!(request["method"], "server/discover");
                write_http_discovery_response(&mut discovery, &serde_json::to_vec(&serde_json::json!({
                    "jsonrpc": "2.0", "id": request["id"], "result": {
                        "supportedVersions": ["2026-07-28"], "capabilities": {"completions": {}},
                        "ttlMs": 0, "cacheScope": "private"
                    }
                })).unwrap());
                drop(discovery);
                let read = |stream: &mut TcpStream| {
                    let request: serde_json::Value =
                        serde_json::from_slice(&read_http_request(stream).body).unwrap();
                    assert_eq!(request["method"], "completion/complete");
                    let params = &request["params"];
                    assert_eq!(
                        params["ref"][if resource { "uri" } else { "name" }],
                        peer_target
                    );
                    if !resource {
                        assert_eq!(params["ref"]["title"], "Completion title");
                    }
                    assert_eq!(
                        params["argument"],
                        serde_json::json!({"name": "subject", "value": peer_target})
                    );
                    assert_eq!(
                        params["context"],
                        serde_json::json!({"arguments": {"language": "rust"}})
                    );
                    assert_eq!(
                        params["_meta"]["io.modelcontextprotocol/protocolVersion"],
                        "2026-07-28"
                    );
                    request
                };
                let mut first = accept();
                let mut first_wire = read(&mut first);
                let mut second = accept();
                let mut second_wire = read(&mut second);
                // IDs are reserved in poll order; connections may arrive in
                // either order. Reply to the second operation first in both cases.
                if first_wire["id"].as_i64().unwrap() > second_wire["id"].as_i64().unwrap() {
                    std::mem::swap(&mut first, &mut second);
                    std::mem::swap(&mut first_wire, &mut second_wire);
                }
                peer_received.store(true, Ordering::Release);
                released
                    .recv_timeout(Duration::from_secs(10))
                    .expect("caller releases completion results");
                let write = |stream: &mut TcpStream, request: &serde_json::Value, suffix: &str| {
                    let body = serde_json::to_vec(&serde_json::json!({"jsonrpc": "2.0", "id": request["id"], "result": {
                        "resultType": "complete", "completion": {"values": [format!("{peer_target}-{suffix}")], "total": 1, "hasMore": false}
                    }})).unwrap();
                    let head = format!(
                        "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                        body.len()
                    );
                    stream
                        .write_all(head.as_bytes())
                        .and_then(|()| stream.write_all(&body))
                };
                write(&mut second, &second_wire, "second").unwrap();
                let first_written = write(&mut first, &first_wire, "first").is_ok();
                if !cancel {
                    assert!(first_written);
                }
                drop(first);
                drop(second);
                let mut recovery = accept();
                let recovery_wire = read(&mut recovery);
                write(&mut recovery, &recovery_wire, "recovery").unwrap();
                vec![first_wire, second_wire, recovery_wire]
            });
            let cx = runtime.request_cx_with_budget(asupersync::Budget::default());
            let plan = ClientProtocolPlan::http(
                ProtocolPolicy::ModernOnly,
                Some(CanonicalHttpUrl::parse(&format!("http://{address}/mcp")).unwrap()),
                None,
                None,
                "completion-credential".to_owned(),
                "completion-owner".to_owned(),
                "native-completion".to_owned(),
                1,
                1,
                0,
            )
            .unwrap();
            let capabilities = ClientCapabilities::default();
            let connection = runtime
                .block_on(ClientHttpConnection::connect(
                    &cx,
                    plan,
                    proxy_http_client_info(),
                    capabilities.clone(),
                ))
                .unwrap();
            let binding = ProxyUpstreamBinding {
                adapter: ProxyUpstreamAdapter::ModernHttp,
                ..proxy_binding(ProtocolEra::Modern2026)
            };
            let proxy = ProxyClient::from_backend_with_upstream_binding(
                ProxyHttpClient::new(
                    binding,
                    connection,
                    cx.clone(),
                    proxy_http_client_info(),
                    capabilities,
                ),
                binding,
                "2026-07-28",
            )
            .unwrap();
            let handler = if resource {
                super::ProxyCompletionHandler::for_resource_template(
                    proxy,
                    format!("gateway/{target}"),
                    &target,
                )
            } else {
                super::ProxyCompletionHandler::for_prompt(
                    proxy,
                    format!("gateway/{target}"),
                    &target,
                )
            };
            let cancellation = McpRequestCancellation::new();
            let first_ctx =
                McpContext::new(cx.clone(), 897).with_request_cancellation(cancellation.clone());
            let second_ctx = McpContext::new(cx.clone(), 898);
            runtime.block_on(async {
                let mut first = std::pin::pin!(invoke_proxy_completion(
                    &handler, &first_ctx, true, resource, &target
                ));
                let mut second = std::pin::pin!(invoke_proxy_completion(
                    &handler,
                    &second_ctx,
                    true,
                    resource,
                    &target
                ));
                let mut first_result = None;
                let mut second_result = None;
                let mut released = false;
                let deadline = Instant::now() + Duration::from_secs(10);
                std::future::poll_fn(|task_cx| {
                    assert!(
                        Instant::now() < deadline,
                        "completion operations are bounded"
                    );
                    if first_result.is_none()
                        && let Poll::Ready(result) = first.as_mut().poll(task_cx)
                    {
                        first_result = Some(result);
                    }
                    if second_result.is_none()
                        && let Poll::Ready(result) = second.as_mut().poll(task_cx)
                    {
                        second_result = Some(result);
                    }
                    if !released && received.load(Ordering::Acquire) {
                        if cancel {
                            assert!(cancellation.cancel());
                        }
                        release.send(()).unwrap();
                        released = true;
                    }
                    if first_result.is_some() && second_result.is_some() {
                        Poll::Ready(())
                    } else {
                        task_cx.waker().wake_by_ref();
                        Poll::Pending
                    }
                })
                .await;
                assert!(released);
                if cancel {
                    assert_eq!(
                        first_result.unwrap().unwrap_err().code,
                        McpErrorCode::RequestCancelled
                    );
                } else {
                    assert_eq!(
                        first_result.unwrap().unwrap()["values"],
                        serde_json::json!([format!("{target}-first")])
                    );
                }
                assert_eq!(
                    second_result.unwrap().unwrap()["values"],
                    serde_json::json!([format!("{target}-second")])
                );
                assert!(second_ctx.checkpoint().is_ok());
                assert_eq!(
                    invoke_proxy_completion(&handler, &second_ctx, true, resource, &target)
                        .await
                        .unwrap()["values"],
                    serde_json::json!([format!("{target}-recovery")])
                );
            });
            let wires = peer.join().expect("completion peer quiesced");
            assert_eq!(wires.len(), 3);
            assert_ne!(wires[0]["id"], wires[1]["id"]);
            eprintln!(
                "{}",
                serde_json::json!({"proof": "proxy_completion_http_caller_runtime", "cancelled": cancel, "resource": resource, "requests": wires})
            );
        }
        assert!(runtime.shutdown_timeout(Duration::from_secs(2)));
    }

    #[cfg(unix)]
    async fn invoke_modern_stdio_handler(
        ctx: &McpContext,
        proxy: ProxyClient,
        method: &str,
        target: &str,
        resume: Option<&crate::bidirectional::MrtrCompletedInputs>,
    ) -> fastmcp_core::McpResult<serde_json::Value> {
        use super::ProxyResourceHandler;
        use crate::handler::{FinalMethodOutcome, FinalToolOutcome, ResourceHandler, UriParams};
        use fastmcp_core::{McpError, Outcome};
        let result = match method {
            "tools/call" => {
                let tool = serde_json::from_value(serde_json::json!({
                    "name": target, "inputSchema": {"type": "object"}
                }))
                .unwrap();
                #[cfg(feature = "tasks")]
                let relay = if ctx.client_supports_tasks() {
                    proxy.final_tasks_relay().unwrap()
                } else {
                    None
                };
                let handler = ProxyToolHandler::with_prefix(tool, "tenant/remote", proxy);
                #[cfg(feature = "tasks")]
                let handler = {
                    let mut handler = handler;
                    handler.task_relay.clone_from(&relay);
                    handler
                };
                match handler
                    .call_final_outcome_async_resuming_in_request(
                        ctx,
                        ctx.cx(),
                        serde_json::json!({"subject": target}),
                        resume,
                    )
                    .await
                {
                    Outcome::Ok(FinalToolOutcome::Complete(result)) => FinalCoreResult::ToolsCall {
                        result,
                        diagnostic: None,
                    },
                    Outcome::Ok(FinalToolOutcome::InputRequired(result)) => {
                        FinalCoreResult::ToolsCallInputRequired {
                            result,
                            diagnostic: None,
                        }
                    }
                    Outcome::Err(error) => return Err(error),
                    #[cfg(feature = "tasks")]
                    Outcome::Ok(FinalToolOutcome::CreateTask {
                        work_descriptor, ..
                    }) => {
                        let result = relay
                            .expect("Tasks must be explicitly negotiated")
                            .admit_carried_task(&work_descriptor)
                            .unwrap()
                            .unwrap();
                        return Ok(serde_json::to_value(result).unwrap());
                    }
                    _ => panic!("stdio tool has a typed final outcome"),
                }
            }
            "resources/read" => {
                let resource =
                    serde_json::from_value(serde_json::json!({"uri": target, "name": target}))
                        .unwrap();
                let handler = ProxyResourceHandler::with_prefix(resource, "tenant/remote", proxy);
                match handler
                    .read_final_outcome_async_with_uri_resuming_in_request(
                        ctx,
                        ctx.cx(),
                        &format!("tenant/remote/{target}"),
                        &UriParams::new(),
                        resume,
                    )
                    .await
                {
                    Outcome::Ok(FinalMethodOutcome::Complete(result)) => {
                        FinalCoreResult::ResourcesRead {
                            result,
                            diagnostic: None,
                        }
                    }
                    Outcome::Ok(FinalMethodOutcome::InputRequired(result)) => {
                        FinalCoreResult::ResourcesReadInputRequired {
                            result,
                            diagnostic: None,
                        }
                    }
                    Outcome::Err(error) => return Err(error),
                    _ => panic!("resource operation has a typed final outcome"),
                }
            }
            "prompts/get" => {
                let prompt = serde_json::from_value(serde_json::json!({"name": target})).unwrap();
                let handler = ProxyPromptHandler::with_prefix(prompt, "tenant/remote", proxy);
                match handler
                    .get_final_outcome_async_resuming_in_request(
                        ctx,
                        ctx.cx(),
                        HashMap::from([("subject".to_owned(), target.to_owned())]),
                        resume,
                    )
                    .await
                {
                    Outcome::Ok(FinalMethodOutcome::Complete(result)) => {
                        FinalCoreResult::PromptsGet {
                            result,
                            diagnostic: None,
                        }
                    }
                    Outcome::Ok(FinalMethodOutcome::InputRequired(result)) => {
                        FinalCoreResult::PromptsGetInputRequired {
                            result,
                            diagnostic: None,
                        }
                    }
                    Outcome::Err(error) => return Err(error),
                    _ => panic!("prompt operation has a typed final outcome"),
                }
            }
            _ => panic!("probe has three real MRTR consumers"),
        };
        serde_json::from_str(&CoreResult::Final(result).encode().unwrap()).map_err(McpError::from)
    }

    #[cfg(unix)]
    fn proxy_modern_stdio_caller_runtime_probe(
        cancel: bool,
        context_deadline: bool,
        task_result: Option<bool>,
    ) {
        use crate::bidirectional::{
            MrtrExchangeBinding, MrtrExchangeRegistry, MrtrInputRequest, MrtrInputRequests,
            MrtrRetry,
        };
        use fastmcp_protocol::{FINAL_CLIENT_CAPABILITIES_META_KEY, FINAL_CLIENT_INFO_META_KEY};
        use std::sync::atomic::{AtomicBool, Ordering};
        let clock = Arc::new(asupersync::time::VirtualClock::new());
        let builder = asupersync::runtime::RuntimeBuilder::current_thread()
            .with_reactor(asupersync::runtime::reactor::create_reactor().unwrap());
        let builder = if context_deadline {
            builder.with_timer_driver(asupersync::time::TimerDriverHandle::with_virtual_clock(
                Arc::clone(&clock),
            ))
        } else {
            builder
        };
        let runtime = builder.build().unwrap();
        let methods: &[&str] = if task_result.is_some() {
            &["tools/call"]
        } else {
            &["tools/call", "resources/read", "prompts/get"]
        };
        for &method in methods {
            for mode in 0..4 {
                let subject = format!(
                    "stdio-{}",
                    std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap()
                        .as_nanos()
                );
                let target = if method == "resources/read" {
                    format!("db://{subject}")
                } else {
                    subject.clone()
                };
                let payload = match (method, task_result) {
                    ("tools/call", Some(true)) => serde_json::json!({
                        "status": "working", "createdAt": "2026-07-28T12:00:00.000Z",
                        "lastUpdatedAt": "2026-07-28T12:00:00.000Z", "ttlMs": null
                    }),
                    ("tools/call", _) => {
                        serde_json::json!({"content": [{"type": "text", "text": subject}]})
                    }
                    ("resources/read", _) => {
                        serde_json::json!({"contents": [{"uri": target, "text": subject}], "ttlMs": 123, "cacheScope": "private"})
                    }
                    _ => {
                        serde_json::json!({"messages": [{"role": "user", "content": {"type": "text", "text": subject}}]})
                    }
                };
                let payload_members = serde_json::to_string(&payload).unwrap();
                let payload_members = &payload_members[1..payload_members.len() - 1];
                let result_type = if task_result == Some(true) {
                    "task"
                } else {
                    "complete"
                };
                let recovery_payload = if task_result == Some(true) {
                    serde_json::json!({"content": [{"type": "text", "text": subject}]})
                } else {
                    payload.clone()
                };
                let recovery_members = serde_json::to_string(&recovery_payload).unwrap();
                let recovery_members = &recovery_members[1..recovery_members.len() - 1];
                let mut discovery: serde_json::Value = serde_json::from_str(
                    &modern_discovery_response_line(&subject, &["2026-07-28"]),
                )
                .unwrap();
                discovery["result"]["capabilities"]["extensions"] =
                    serde_json::json!({"io.modelcontextprotocol/tasks": {}});
                let discovery = serde_json::to_string(&discovery).unwrap();
                let pairs = if mode == 0 { 1 } else { 2 };
                // The child withholds both replies until two real requests
                // arrive. A synchronous first request prevents the second
                // caller-runtime task from sending and hits the client bound.
                let script = format!(
                    r#"
IFS= read -r discovery || exit 90
printf '%s\n' '{discovery}'
wires=''
control=null
id=2
pair=0
while [ "$pair" -lt {pairs} ]; do
  IFS= read -r first || exit 91
  IFS= read -r second || exit 92
  if [ -n "$wires" ]; then wires="$wires,$first,$second"; else wires="$first,$second"; fi
  next=$((id+1))
  if [ "$pair" -eq $(({pairs}-1)) ] && [ '{cancel}' = true ]; then
    IFS= read -r control || exit 93
  fi
  printf '%s\n' '{{"jsonrpc":"2.0","method":"notifications/progress","params":{{"progressToken":"first","progress":1.20e+4,"total":12000.0}}}}'
  printf '%s\n' '{{"jsonrpc":"2.0","method":"notifications/progress","params":{{"progressToken":"second","progress":1.20e+4,"total":12000.0}}}}'
  for response_id in "$next" "$id"; do
    if [ '{mode}' -ne 0 ] && [ "$pair" -eq 0 ]; then
      state=''
      inputs=''
      if [ '{mode}' -ne 3 ]; then state=',"requestState":"{subject}-'"$response_id"'"'; fi
      if [ '{mode}' -ge 2 ]; then inputs=',"inputRequests":{{"roots":{{"method":"roots/list"}}}}'; fi
      printf '{{"jsonrpc":"2.0","id":%s,"result":{{"resultType":"input_required"%s%s}}}}\n' "$response_id" "$state" "$inputs"
    else
      task=''
      if [ '{result_type}' = task ]; then task=',"taskId":"{subject}-'"$response_id"'"'; fi
      printf '{{"jsonrpc":"2.0","id":%s,"result":{{"resultType":"{result_type}",{payload_members}%s,"_meta":{{"owner":%s}}}}}}\n' "$response_id" "$task" "$response_id"
    fi
  done
  id=$((id+2))
  pair=$((pair+1))
done
IFS= read -r recovery || exit 94
printf '{{"jsonrpc":"2.0","id":%s,"result":{{"resultType":"complete",{recovery_members},"_meta":{{"wires":[%s],"control":%s,"recovery":%s}}}}}}\n' "$id" "$wires" "$control" "$recovery"
IFS= read -r end
"#
                );
                let cx = runtime.request_cx_with_budget(asupersync::Budget::default());
                let mut client = Client::stdio_with_protocol_plan_with_cx(
                    "sh",
                    &["-c", &script],
                    ClientProtocolPlan::stdio(ProtocolPolicy::ModernOnly),
                    cx.clone(),
                )
                .unwrap();
                client
                    .set_request_timeout_policy(
                        fastmcp_client::RequestTimeoutPolicy::new(
                            Duration::from_secs(2),
                            Duration::from_secs(4),
                        )
                        .unwrap(),
                    )
                    .unwrap();
                let proxy = ProxyClient::from_client(client).unwrap();
                let capture = Arc::new(ExactProgressCapture::default());
                let cancellation = McpRequestCancellation::new();
                let registry = MrtrExchangeRegistry::new();
                let binding = MrtrExchangeBinding::new(
                    method,
                    target.clone(),
                    [3; 32],
                    [4; 32],
                    None,
                    [5; 32],
                );
                runtime.block_on(async {
                    let mut resumes = Vec::new();
                    let mut expected_tasks = serde_json::Map::new();
                    for pair in 0..pairs {
                        let cancelling_pair = cancel && pair + 1 == pairs;
                        let make_ctx = |marker: &str| {
                            let capabilities = fastmcp_core::ClientCapabilityInfo::new().with_roots(false);
                            #[cfg(feature = "tasks")]
                            let capabilities = if task_result.is_some() { capabilities.with_tasks() } else { capabilities };
                            McpContext::with_progress(cx.clone(), 893,
                                ProgressReporter::with_marker(serde_json::json!(marker), Arc::clone(&capture) as Arc<dyn NotificationSender>))
                                .with_client_capabilities(capabilities)
                                .with_client_implementation(fastmcp_core::ClientImplementationInfo::new(subject.clone(), "18"))
                        };
                        let first_ctx = make_ctx("first").with_request_cancellation(cancellation.clone());
                        let second_ctx = make_ctx("second");
                        let started = Arc::new(AtomicBool::new(false));
                        let observer_started = Arc::clone(&started);
                        let observer_cancellation = cancellation.clone();
                        let observer_clock = Arc::clone(&clock);
                        let mut observer = cx.spawn(move |observer_cx| async move {
                            let deadline = Instant::now() + Duration::from_secs(3);
                            while !observer_started.load(Ordering::Acquire) {
                                assert!(Instant::now() < deadline, "second request starts within its bound");
                                asupersync::runtime::yield_now().await;
                            }
                            if context_deadline {
                                // Expire the same 100ms MCP deadline only after
                                // both real requests committed and yielded.
                                // Scheduler delays cannot erase that witness.
                                observer_clock.advance(100_000_000);
                            }
                            if cancelling_pair && !context_deadline {
                                asupersync::time::sleep(observer_cx.now(), Duration::from_millis(20)).await;
                                assert!(observer_cancellation.cancel());
                            }
                        }).unwrap();
                        let first_pending = Arc::new(AtomicBool::new(false));
                        let pending_signal = Arc::clone(&first_pending);
                        let worker_thread = Arc::new(Mutex::new(None));
                        let first_thread = Arc::clone(&worker_thread);
                        let first_proxy = proxy.clone();
                        let first_target = target.clone();
                        let first_resume = resumes.first().cloned();
                        // Runtime::block_on polls its root on the driving
                        // thread. Put BOTH operations on the single worker,
                        // and observe Pending only after the first releases
                        // its bounded receive guard.
                        let mut first_request = cx.spawn(move |first_cx| async move {
                            *first_thread.lock().unwrap() = Some(thread::current().id());
                            let first_ctx = if context_deadline {
                                first_ctx.with_operation_deadline(Some(first_cx.now().saturating_add_nanos(
                                    if cancelling_pair { 100_000_000 } else { 5_000_000_000 })))
                            } else { first_ctx };
                            let deadline = first_ctx.budget().deadline;
                            let mut request = Box::pin(invoke_modern_stdio_handler(&first_ctx, first_proxy, method, &first_target, first_resume.as_ref()));
                            let result = std::future::poll_fn(|task_cx| {
                                let poll = request.as_mut().poll(task_cx);
                                if poll.is_pending() { pending_signal.store(true, Ordering::Release); }
                                poll
                            }).await;
                            (result, deadline)
                        }).unwrap();
                        let second_proxy = proxy.clone();
                        let second_target = target.clone();
                        let second_resume = resumes.get(1).cloned();
                        let mut sibling = cx.spawn(move |_sibling_cx| async move {
                            let deadline = Instant::now() + Duration::from_secs(3);
                            while !first_pending.load(Ordering::Acquire) {
                                assert!(Instant::now() < deadline, "first request yields within its bound");
                                asupersync::runtime::yield_now().await;
                            }
                            assert_eq!(*worker_thread.lock().unwrap(), Some(thread::current().id()), "both operations run on the same caller worker");
                            assert!(second_proxy.inner.try_lock().is_ok(), "first request released backend lock");
                            let mut request = Box::pin(invoke_modern_stdio_handler(&second_ctx, second_proxy, method, &second_target, second_resume.as_ref()));
                            std::future::poll_fn(|task_cx| {
                                let poll = request.as_mut().poll(task_cx);
                                // Ready also releases the bounded observer on
                                // the positive fast-response path.
                                started.store(true, Ordering::Release);
                                poll
                            }).await
                        }).unwrap();
                        let (first, first_deadline) = first_request.join(&cx).await.unwrap();
                        let second = sibling.join(&cx).await.unwrap().unwrap();
                        observer.join(&cx).await.unwrap();
                        if cancelling_pair {
                            assert_eq!(first.unwrap_err().code, McpErrorCode::RequestCancelled);
                            if context_deadline {
                                assert!(!cancellation.is_cancel_requested());
                                assert!(!cx.is_cancel_requested());
                                assert!(cx.now() >= first_deadline.unwrap());
                            }
                            assert_eq!(second["resultType"], result_type);
                            assert_eq!(second["_meta"]["owner"], 3 + pair*2);
                            for (key, value) in payload.as_object().unwrap() { assert_eq!(&second[key], value); }
                            if task_result == Some(true) {
                                assert_eq!(second["taskId"], format!("{subject}-{}", 3 + pair*2));
                                let mut task = second.as_object().unwrap().clone();
                                task.remove("resultType");
                                task.remove("_meta");
                                expected_tasks.insert(second["taskId"].as_str().unwrap().to_owned(), serde_json::Value::Object(task));
                            }
                        } else {
                            let first = first.unwrap();
                            if mode != 0 && pair == 0 {
                                for (index, result) in [first, second].into_iter().enumerate() {
                                    assert_eq!(result["resultType"], "input_required");
                                    let state = format!("{subject}-{}", index+2);
                                    assert_eq!(result.get("requestState").and_then(serde_json::Value::as_str), (mode != 3).then_some(state.as_str()));
                                    let inputs = if mode >= 2 { MrtrInputRequests::new([("roots".to_owned(), MrtrInputRequest::roots())]).unwrap() } else { MrtrInputRequests::default() };
                                    let issued = registry.issue_bound(cancellation.clone(), binding.clone(), inputs, result.get("requestState").and_then(serde_json::Value::as_str).map(str::to_owned)).unwrap();
                                    let issued = serde_json::to_value(issued).unwrap();
                                    let token = issued["requestState"].as_str().unwrap();
                                    let retry = if mode >= 2 {
                                        registry.accept_wire_bound(token, &binding, &BTreeMap::from([("roots".to_owned(), serde_json::json!({"roots": [{"uri": format!("file:///{subject}-{index}")}]}))])).unwrap()
                                    } else { registry.accept_state_only_bound(token, &binding).unwrap() };
                                    let MrtrRetry::Complete(inputs) = retry else { panic!("continuation inputs admitted"); };
                                    resumes.push(inputs);
                                }
                            } else {
                                assert_eq!(first["_meta"]["owner"], 2 + pair*2);
                                assert_eq!(second["_meta"]["owner"], 3 + pair*2);
                                for result in [&first, &second] {
                                    assert_eq!(result["resultType"], result_type);
                                    for (key, value) in payload.as_object().unwrap() { assert_eq!(&result[key], value); }
                                    if task_result == Some(true) {
                                        assert_eq!(result["taskId"], format!("{subject}-{}", result["_meta"]["owner"]));
                                        let mut task = result.as_object().unwrap().clone();
                                        task.remove("resultType");
                                        task.remove("_meta");
                                        expected_tasks.insert(result["taskId"].as_str().unwrap().to_owned(), serde_json::Value::Object(task));
                                    }
                                }
                            }
                        }
                    }
                    let recovery = invoke_modern_stdio_handler(&McpContext::new(cx.clone(), 894), proxy.clone(), method, &target, None).await.unwrap();
                    let meta = &recovery["_meta"];
                    let wires = meta["wires"].as_array().unwrap();
                    assert_eq!(wires.len(), pairs*2);
                    for (index, wire) in wires.iter().enumerate() {
                        assert_eq!(wire["id"], index+2);
                        assert_eq!(wire["method"], method);
                        let params = &wire["params"];
                        assert_eq!(params[if method == "resources/read" { "uri" } else { "name" }], target);
                        assert_eq!(params["_meta"]["io.modelcontextprotocol/protocolVersion"], "2026-07-28");
                        assert_eq!(params["_meta"][FINAL_CLIENT_INFO_META_KEY]["name"], subject);
                        assert_eq!(params["_meta"]["progressToken"], if index % 2 == 0 { "first" } else { "second" });
                        let tasks = params["_meta"][FINAL_CLIENT_CAPABILITIES_META_KEY]["extensions"].get("io.modelcontextprotocol/tasks");
                        if task_result.is_some() { assert_eq!(tasks, Some(&serde_json::json!({}))); }
                        else { assert!(tasks.is_none()); }
                        assert_eq!(params.get("requestState"), (index >= 2 && mode != 3).then(|| serde_json::json!(format!("{subject}-{}", index))).as_ref());
                        assert_eq!(params.get("inputResponses"), (index >= 2 && mode >= 2).then(|| serde_json::json!({"roots": {"roots": [{"uri": format!("file:///{subject}-{}", index-2)}]}})).as_ref());
                    }
                    assert_eq!(meta["recovery"]["id"], 2+pairs*2);
                    if cancel {
                        assert_eq!(meta["control"]["method"], "notifications/cancelled");
                        assert_eq!(meta["control"]["params"]["requestId"], pairs*2);
                    } else { assert!(meta["control"].is_null()); }
                    assert_eq!(registry.active_len(), 0);
                    #[cfg(feature = "tasks")]
                    let task_snapshot = proxy.final_task_registry_snapshot_for_test().unwrap();
                    #[cfg(feature = "tasks")]
                    assert_eq!(task_snapshot, serde_json::json!({"pendingCreations": 0, "tasks": expected_tasks}));
                    #[cfg(not(feature = "tasks"))]
                    let task_snapshot = serde_json::Value::Null;
                    eprintln!("{}", serde_json::json!({"proof": if task_result.is_some() { "proxy_stdio_task_tool_caller_runtime" } else { "proxy_modern_stdio_caller_runtime" }, "task_result": task_result, "method": method, "mode": mode, "cancelled": cancel, "context_deadline": context_deadline, "subject": subject, "task_registry": task_snapshot, "peer": meta}));
                });
                let progress = capture.values.lock().unwrap();
                assert_eq!(progress.len(), pairs * 2 - usize::from(cancel));
                for (value, total, message) in progress.iter() {
                    assert_eq!(value, "1.20e+4");
                    assert_eq!(total.as_deref(), Some("12000.0"));
                    assert!(message.is_none());
                }
            }
        }
        assert!(runtime.shutdown_timeout(Duration::from_secs(2)));
    }

