    #[cfg(feature = "tasks")]
    #[test]
    fn stdio_inbound_capability_overlay_preserves_official_tasks_extension() {
        let parameters = stdio_parameters_with_inbound_identity(
            Some(ProtocolEra::Modern2026),
            serde_json::json!({
                "_meta": {
                    fastmcp_protocol::FINAL_CLIENT_CAPABILITIES_META_KEY: {
                        "extensions": { fastmcp_protocol::TASKS_EXTENSION: {} }
                    }
                }
            }),
            None,
            None,
            Some(ClientCapabilities::default()),
        );
        assert_eq!(
            parameters["_meta"][fastmcp_protocol::FINAL_CLIENT_CAPABILITIES_META_KEY]["extensions"]
                [fastmcp_protocol::TASKS_EXTENSION],
            serde_json::json!({}),
            "an empty inbound overlay must keep already-stamped official Tasks: {parameters:?}"
        );
        assert!(
            parameters["_meta"][fastmcp_protocol::FINAL_CLIENT_CAPABILITIES_META_KEY]
                .get("sampling")
                .is_none(),
            "empty inbound capabilities must not invent sampling: {parameters:?}"
        );
    }

    #[test]
    fn stdio_inbound_identity_overlay_is_skipped_on_exact_2024() {
        let parameters = stdio_parameters_with_inbound_identity(
            Some(ProtocolEra::Legacy2024),
            serde_json::json!({"uri": "file:///e2e/note.txt"}),
            None,
            None,
            Some(ClientCapabilities::default()),
        );
        assert!(
            parameters.get("_meta").is_none(),
            "exact-2024 stdio as_proxy must not stamp reserved final _meta: {parameters:?}"
        );
        assert_eq!(
            parameters["uri"], "file:///e2e/note.txt",
            "exact-2024 stdio as_proxy must keep the rewritten file URI: {parameters:?}"
        );
    }

    #[test]
    fn custom_backend_does_not_pretend_to_own_an_incremental_catalog_listener() {
        let runtime = asupersync::runtime::RuntimeBuilder::current_thread()
            .build()
            .expect("caller runtime builds");
        runtime.block_on(async {
            let cx = Cx::current().expect("caller runtime supplies a context");
            let proxy = ProxyClient::from_backend(TestBackend::default());
            assert!(
                !proxy
                    .start_catalog_listener(
                        &cx,
                        SubscriptionFilter {
                            tools_list_changed: Some(true),
                            ..SubscriptionFilter::default()
                        }
                    )
                    .await
                    .expect("a custom backend must answer the incremental catalog reservation"),
                "only a sequential stdio backend can own the live catalog listener"
            );
            let error = proxy
                .next_catalog_listener_event(&cx, &McpRequestCancellation::new())
                .await
                .expect_err("polling without a reserved incremental listener must fail closed");
            assert_eq!(error.code, McpErrorCode::InvalidRequest);
            assert!(error.message.contains("incremental catalog listener"));
        });
    }

    #[cfg(unix)]
    async fn open_incremental_listener_probe(
        proxy: &ProxyClient,
        cx: &Cx,
        filter: SubscriptionFilter,
        tasks: bool,
    ) -> fastmcp_core::McpResult<bool> {
        #[cfg(feature = "tasks")]
        if tasks {
            return proxy.start_final_task_listener(cx, filter).await;
        }
        assert!(!tasks, "Tasks probes require the Tasks feature");
        proxy.start_catalog_listener(cx, filter).await
    }

    #[cfg(unix)]
    async fn next_incremental_listener_probe(
        proxy: &ProxyClient,
        cx: &Cx,
        cancellation: &McpRequestCancellation,
        tasks: bool,
    ) -> fastmcp_core::McpResult<bool> {
        #[cfg(feature = "tasks")]
        if tasks {
            return match proxy
                .next_final_task_listener_event(cx, cancellation)
                .await?
            {
                fastmcp_client::StdioTaskSubscriptionEvent::Acknowledged(_) => Ok(false),
                fastmcp_client::StdioTaskSubscriptionEvent::Terminal => Ok(true),
                event => panic!("unexpected Tasks listener event: {event:?}"),
            };
        }
        assert!(!tasks, "Tasks probes require the Tasks feature");
        match proxy.next_catalog_listener_event(cx, cancellation).await? {
            fastmcp_client::StdioSubscriptionEvent::Acknowledged(_) => Ok(false),
            fastmcp_client::StdioSubscriptionEvent::Terminal => Ok(true),
            event => panic!("unexpected catalog listener event: {event:?}"),
        }
    }

    #[cfg(unix)]
    fn proxy_incremental_listener_caller_runtime_probe(tasks: bool, interrupt: Option<bool>) {
        use std::future::Future;
        use std::sync::atomic::{AtomicUsize, Ordering};
        use std::task::Poll;

        let runtime = asupersync::runtime::RuntimeBuilder::current_thread()
            .with_reactor(asupersync::runtime::reactor::create_reactor().unwrap())
            .blocking_threads(0, 0)
            .build()
            .unwrap();
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        listener.set_nonblocking(true).unwrap();
        let address = listener.local_addr().unwrap();
        let subject = format!("listener-{}", address.port());
        let mut filter = SubscriptionFilter::default();
        if tasks {
            #[cfg(feature = "tasks")]
            set_task_subscription_ids(
                &mut filter,
                vec![fastmcp_protocol::FinalTaskId::parse(subject.clone()).unwrap()],
            )
            .unwrap();
            #[cfg(not(feature = "tasks"))]
            panic!("Tasks probes require the Tasks feature");
        } else {
            filter.tools_list_changed = Some(true);
        }
        let expected_filter = serde_json::to_value(&filter).unwrap();
        let received = Arc::new(AtomicUsize::new(0));
        let peer_received = Arc::clone(&received);
        let (release, released) = std::sync::mpsc::sync_channel(1);
        let peer = thread::spawn(move || {
            let accept = || {
                let deadline = Instant::now() + Duration::from_secs(10);
                loop {
                    match listener.accept() {
                        Ok((stream, _)) => {
                            stream
                                .set_read_timeout(Some(Duration::from_secs(10)))
                                .unwrap();
                            stream
                                .set_write_timeout(Some(Duration::from_secs(10)))
                                .unwrap();
                            return stream;
                        }
                        Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                            assert!(Instant::now() < deadline, "listener peer accept is bounded");
                            thread::sleep(Duration::from_millis(1));
                        }
                        Err(error) => panic!("listener peer accept: {error}"),
                    }
                }
            };
            let mut discovery = accept();
            let request: serde_json::Value =
                serde_json::from_slice(&read_http_request(&mut discovery).body).unwrap();
            assert_eq!(request["method"], "server/discover");
            write_http_discovery_response(&mut discovery, &serde_json::to_vec(&serde_json::json!({
                "jsonrpc": "2.0", "id": request["id"], "result": {
                    "supportedVersions": ["2026-07-28"],
                    "capabilities": {"tools": {}, "extensions": {"io.modelcontextprotocol/tasks": {}}},
                    "ttlMs": 0, "cacheScope": "private"
                }
            })).unwrap());
            drop(discovery);
            let attempts = if interrupt.is_some() { 2 } else { 1 };
            let mut requests = Vec::new();
            for attempt in 0..attempts {
                let mut stream = accept();
                let request: serde_json::Value =
                    serde_json::from_slice(&read_http_request(&mut stream).body).unwrap();
                assert_eq!(request["method"], "subscriptions/listen");
                assert_eq!(request["params"]["notifications"], expected_filter);
                assert_eq!(request["id"], 2 + attempt);
                requests.push(request.clone());
                peer_received.store(attempt + 1, Ordering::Release);
                let abort = released
                    .recv_timeout(Duration::from_secs(10))
                    .expect("caller runtime releases the delayed HTTP handshake");
                if abort {
                    let mut byte = [0];
                    match stream.read(&mut byte) {
                        Ok(0) => {}
                        Err(error)
                            if matches!(
                                error.kind(),
                                std::io::ErrorKind::ConnectionReset
                                    | std::io::ErrorKind::BrokenPipe
                            ) => {}
                        other => panic!("dropped opening must close its native socket: {other:?}"),
                    }
                    continue;
                }
                stream.write_all(b"HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nTransfer-Encoding: chunked\r\nConnection: close\r\n\r\n").unwrap();
                let ack = serde_json::json!({"jsonrpc": "2.0", "method": "notifications/subscriptions/acknowledged", "params": {
                    "_meta": {"io.modelcontextprotocol/subscriptionId": request["id"]},
                    "notifications": expected_filter
                }});
                write_chunked_sse_event(&mut stream, format!("data: {ack}\n\n").as_bytes());
                stream.flush().unwrap();
                assert!(
                    !released
                        .recv_timeout(Duration::from_secs(10))
                        .expect("caller releases terminal event")
                );
                let terminal = serde_json::json!({"jsonrpc": "2.0", "id": request["id"], "result": {
                    "resultType": "complete", "_meta": {"io.modelcontextprotocol/subscriptionId": request["id"]}
                }});
                write_chunked_sse_event(&mut stream, format!("data: {terminal}\n\n").as_bytes());
                stream.write_all(b"0\r\n\r\n").unwrap();
            }
            requests
        });
        let cx = runtime.request_cx_with_budget(asupersync::Budget::default());
        let plan = ClientProtocolPlan::http(
            ProtocolPolicy::ModernOnly,
            Some(CanonicalHttpUrl::parse(&format!("http://{address}/mcp")).unwrap()),
            None,
            None,
            subject.clone(),
            subject.clone(),
            subject,
            1,
            1,
            0,
        )
        .unwrap();
        let capabilities = ClientCapabilities::default();
        let connection = runtime
            .block_on(ClientHttpConnection::connect(
                &cx,
                plan,
                proxy_http_client_info(),
                capabilities.clone(),
            ))
            .unwrap();
        let binding = ProxyUpstreamBinding {
            adapter: ProxyUpstreamAdapter::ModernHttp,
            ..proxy_binding(ProtocolEra::Modern2026)
        };
        let proxy = ProxyClient::from_backend_with_upstream_binding(
            ProxyHttpClient::new(
                binding,
                connection,
                cx.clone(),
                proxy_http_client_info(),
                capabilities,
            ),
            binding,
            "2026-07-28",
        )
        .unwrap();
        runtime.block_on(async {
            let root = Cx::current().unwrap();
            let sibling_root = root.clone();
            let proxy = proxy.clone();
            let cx = cx.clone();
            let mut work = root
                .spawn(move |_| async move {
                    let root = sibling_root;
                    let worker = thread::current().id();
                    if interrupt.is_some() {
                        cx.set_cancel_requested(true);
                        let error =
                            open_incremental_listener_probe(&proxy, &cx, filter.clone(), tasks)
                                .await
                                .unwrap_err();
                        assert_eq!(error.code, McpErrorCode::RequestCancelled);
                        assert_eq!(received.load(Ordering::Acquire), 0);
                        cx.set_cancel_requested(false);
                    }
                    let attempts = if interrupt.is_some() { 2 } else { 1 };
                    for attempt in 0..attempts {
                        let mut opening = Box::pin(open_incremental_listener_probe(
                            &proxy,
                            &cx,
                            filter.clone(),
                            tasks,
                        ));
                        let deadline = Instant::now() + Duration::from_secs(10);
                        loop {
                            assert!(
                                std::future::poll_fn(|task_cx| Poll::Ready(
                                    opening.as_mut().poll(task_cx)
                                ))
                                .await
                                .is_pending(),
                                "handshake must yield while peer withholds HTTP headers"
                            );
                            if received.load(Ordering::Acquire) > attempt {
                                break;
                            }
                            assert!(Instant::now() < deadline, "listen request reaches peer");
                            asupersync::time::sleep(root.now(), Duration::from_millis(1)).await;
                        }
                        // Reservation refuses a second opening without a second POST.
                        let error =
                            open_incremental_listener_probe(&proxy, &cx, filter.clone(), tasks)
                                .await
                                .unwrap_err();
                        assert_eq!(error.code, McpErrorCode::InvalidRequest);
                        if attempt == 0
                            && let Some(cancel) = interrupt
                        {
                            if cancel {
                                let cancelling_cx = cx.clone();
                                let mut cancelling = root
                                    .spawn(move |sibling_cx| async move {
                                        assert_eq!(thread::current().id(), worker);
                                        asupersync::time::sleep(
                                            sibling_cx.now(),
                                            Duration::from_millis(10),
                                        )
                                        .await;
                                        cancelling_cx.set_cancel_requested(true);
                                    })
                                    .unwrap();
                                assert_eq!(
                                    opening.await.unwrap_err().code,
                                    McpErrorCode::RequestCancelled
                                );
                                cancelling.join(&root).await.unwrap();
                                cx.set_cancel_requested(false);
                            } else {
                                drop(opening);
                            }
                            release.send(true).unwrap();
                            continue;
                        }
                        let release_headers = release.clone();
                        let mut sibling = root
                            .spawn(move |_| async move {
                                assert_eq!(thread::current().id(), worker);
                                release_headers.send(false).unwrap();
                                1_u8
                            })
                            .unwrap();
                        assert_eq!(sibling.join(&root).await.unwrap(), 1);
                        assert!(opening.await.unwrap());
                    }
                    let cancellation = McpRequestCancellation::new();
                    assert!(
                        !next_incremental_listener_probe(&proxy, &cx, &cancellation, tasks)
                            .await
                            .unwrap()
                    );
                    let mut next = Box::pin(next_incremental_listener_probe(
                        &proxy,
                        &cx,
                        &cancellation,
                        tasks,
                    ));
                    assert!(
                        std::future::poll_fn(|task_cx| Poll::Ready(next.as_mut().poll(task_cx)))
                            .await
                            .is_pending(),
                        "event read yields before peer terminal"
                    );
                    drop(next);
                    let mut sibling = root
                        .spawn(move |_| async move {
                            assert_eq!(thread::current().id(), worker);
                            release.send(false).unwrap();
                            2_u8
                        })
                        .unwrap();
                    assert_eq!(sibling.join(&root).await.unwrap(), 2);
                    assert!(
                        next_incremental_listener_probe(&proxy, &cx, &cancellation, tasks)
                            .await
                            .unwrap()
                    );
                })
                .unwrap();
            work.join(&root).await.unwrap();
        });
        drop(proxy);
        let requests = peer.join().unwrap();
        assert_eq!(requests.len(), if interrupt.is_some() { 2 } else { 1 });
        assert!(runtime.shutdown_timeout(Duration::from_secs(2)));
    }

    #[cfg(unix)]
    #[test]
    fn proxy_incremental_listener_caller_runtime_positive() {
        proxy_incremental_listener_caller_runtime_probe(false, None);
        #[cfg(feature = "tasks")]
        proxy_incremental_listener_caller_runtime_probe(true, None);
    }

    #[cfg(unix)]
    fn proxy_http_registry_caller_runtime_probe(legacy: bool, interrupt: u8) {
        use std::future::Future;
        use std::sync::atomic::{AtomicUsize, Ordering};
        use std::task::Poll;

        let clock = Arc::new(asupersync::time::VirtualClock::new());
        let builder = asupersync::runtime::RuntimeBuilder::current_thread()
            .with_reactor(asupersync::runtime::reactor::create_reactor().unwrap())
            .blocking_threads(0, 0);
        let builder = if matches!(interrupt, 3 | 5) {
            builder.with_timer_driver(asupersync::time::TimerDriverHandle::with_virtual_clock(
                Arc::clone(&clock),
            ))
        } else {
            builder
        };
        let runtime = builder.build().unwrap();
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        listener.set_nonblocking(true).unwrap();
        let address = listener.local_addr().unwrap();
        let subject = format!("registry-{}", address.port());
        let endpoint = format!("http://{address}/message?owner={subject}");
        let plan = if legacy {
            legacy_only_http_proxy_plan(&format!("http://{address}/sse"), &endpoint)
        } else {
            ClientProtocolPlan::http(
                ProtocolPolicy::ModernOnly,
                Some(CanonicalHttpUrl::parse(&format!("http://{address}/mcp")).unwrap()),
                None,
                None,
                subject.clone(),
                subject.clone(),
                subject.clone(),
                1,
                1,
                0,
            )
            .unwrap()
        };
        let received = Arc::new(AtomicUsize::new(0));
        let peer_received = Arc::clone(&received);
        let (release, released) = std::sync::mpsc::sync_channel(1);
        let interrupted_opening = matches!(interrupt, 1..=3);
        let attempts = if interrupted_opening { 2 } else { 1 };
        let peer = thread::spawn(move || {
            let accept = || {
                let deadline = Instant::now() + Duration::from_secs(10);
                loop {
                    match listener.accept() {
                        Ok((stream, _)) => {
                            stream
                                .set_read_timeout(Some(Duration::from_secs(10)))
                                .unwrap();
                            stream
                                .set_write_timeout(Some(Duration::from_secs(10)))
                                .unwrap();
                            return stream;
                        }
                        Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                            assert!(Instant::now() < deadline, "registry peer accept is bounded");
                            thread::sleep(Duration::from_millis(1));
                        }
                        Err(error) => panic!("registry peer accept: {error}"),
                    }
                }
            };
            for attempt in 0..attempts {
                let mut stream = accept();
                let opening = read_http_request(&mut stream);
                let request: serde_json::Value = if legacy {
                    assert!(opening.head.starts_with("GET /sse HTTP/1.1\r\n"));
                    stream.write_all(b"HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nTransfer-Encoding: chunked\r\nConnection: close\r\n\r\n").unwrap();
                    write_chunked_sse_event(
                        &mut stream,
                        format!("event: endpoint\ndata: {endpoint}\n\n").as_bytes(),
                    );
                    stream.flush().unwrap();
                    let mut post = accept();
                    let initialization = read_http_request(&mut post);
                    assert!(
                        initialization
                            .head
                            .starts_with("POST /message?owner=registry-")
                    );
                    let request: serde_json::Value =
                        serde_json::from_slice(&initialization.body).unwrap();
                    assert_eq!(request["method"], "initialize");
                    assert_eq!(request["params"]["protocolVersion"], "2024-11-05");
                    write_http_response(&mut post, 202, "application/json", b"");
                    request
                } else {
                    assert!(opening.head.starts_with("POST /mcp HTTP/1.1\r\n"));
                    let request: serde_json::Value = serde_json::from_slice(&opening.body).unwrap();
                    assert_eq!(request["method"], "server/discover");
                    request
                };
                assert_eq!(request["id"], 1, "retry uses a fresh connection");
                peer_received.store(attempt + 1, Ordering::Release);
                if released.recv_timeout(Duration::from_secs(10)).unwrap() {
                    let mut byte = [0];
                    match stream.read(&mut byte) {
                        Ok(0) => {}
                        Err(error)
                            if matches!(
                                error.kind(),
                                std::io::ErrorKind::ConnectionReset
                                    | std::io::ErrorKind::BrokenPipe
                            ) => {}
                        other => {
                            panic!("abandoned connection must close its native socket: {other:?}")
                        }
                    }
                    continue;
                }
                let result = if legacy {
                    serde_json::json!({"protocolVersion":"2024-11-05", "capabilities":{}, "serverInfo":{"name":"registry-peer","version":"1"}})
                } else {
                    serde_json::json!({"supportedVersions":["2026-07-28"], "capabilities":{"tools":{}}, "ttlMs":0,"cacheScope":"private"})
                };
                let response =
                    serde_json::json!({"jsonrpc":"2.0", "id":request["id"], "result":result});
                if legacy {
                    write_chunked_sse_event(
                        &mut stream,
                        format!("event: message\ndata: {response}\n\n").as_bytes(),
                    );
                    stream.flush().unwrap();
                    let mut post = accept();
                    let initialized: serde_json::Value =
                        serde_json::from_slice(&read_http_request(&mut post).body).unwrap();
                    assert_eq!(initialized["method"], "notifications/initialized");
                    assert!(initialized.get("id").is_none());
                    write_http_response(&mut post, 202, "application/json", b"");
                } else {
                    write_http_discovery_response(
                        &mut stream,
                        &serde_json::to_vec(&response).unwrap(),
                    );
                }
                let methods: &[&str] = if interrupt == 4 {
                    &["tools/list", "tools/list"]
                } else {
                    &[
                        "tools/list",
                        "tools/list",
                        "resources/list",
                        "resources/templates/list",
                        "prompts/list",
                    ]
                };
                for (index, method) in methods.iter().enumerate() {
                    let mut post = accept();
                    let message: serde_json::Value =
                        serde_json::from_slice(&read_http_request(&mut post).body).unwrap();
                    assert_eq!(message["method"], *method);
                    assert_eq!(message["id"], index + 2);
                    if index == 0 {
                        peer_received.store(attempts + 1, Ordering::Release);
                        if released.recv_timeout(Duration::from_secs(10)).unwrap() {
                            let mut byte = [0];
                            assert!(matches!(post.read(&mut byte), Ok(0)));
                            break;
                        }
                    }
                    let mut result = match *method {
                        "tools/list" => {
                            serde_json::json!({"tools":[{"name":format!("registry-{}-{index}", address.port()), "inputSchema":{"type":"object"}}]})
                        }
                        "resources/list" => serde_json::json!({"resources":[]}),
                        "resources/templates/list" => serde_json::json!({"resourceTemplates":[]}),
                        "prompts/list" => serde_json::json!({"prompts":[]}),
                        _ => unreachable!(),
                    };
                    if index == 0 || (index == 1 && interrupt == 4) {
                        result["nextCursor"] = serde_json::json!("page-two");
                    }
                    if index == 1 {
                        assert_eq!(message["params"]["cursor"], "page-two");
                    }
                    if !legacy {
                        result["resultType"] = serde_json::json!("complete");
                        result["ttlMs"] = serde_json::json!(index + 17);
                        result["cacheScope"] = serde_json::json!("private");
                    }
                    let response =
                        serde_json::json!({"jsonrpc":"2.0", "id":message["id"], "result":result});
                    if legacy {
                        write_http_response(&mut post, 202, "application/json", b"");
                        write_chunked_sse_event(
                            &mut stream,
                            format!("event: message\ndata: {response}\n\n").as_bytes(),
                        );
                        stream.flush().unwrap();
                    } else {
                        write_http_response(
                            &mut post,
                            200,
                            "application/json",
                            &serde_json::to_vec(&response).unwrap(),
                        );
                    }
                }
                if legacy {
                    assert!(!released.recv_timeout(Duration::from_secs(10)).unwrap());
                }
            }
        });
        let cx = runtime.request_cx_with_budget(asupersync::Budget::INFINITE);
        let opening_cx = runtime.request_cx_with_budget(if interrupt == 3 {
            asupersync::Budget::INFINITE.with_deadline(cx.now().saturating_add_nanos(100_000_000))
        } else {
            asupersync::Budget::INFINITE
        });
        let catalog_cx = runtime.request_cx_with_budget(if interrupt == 5 {
            asupersync::Budget::INFINITE.with_deadline(cx.now().saturating_add_nanos(100_000_000))
        } else {
            asupersync::Budget::INFINITE
        });
        runtime.block_on(async {
            let root = Cx::current().unwrap();
            let siblings = root.clone();
            let mut work = root
                .spawn(move |_| async move {
                    let worker = thread::current().id();
                    let mut registry = ProxyClient::upstream_binding_registry();
                    if interrupt != 0 {
                        cx.set_cancel_requested(true);
                        assert_eq!(
                            registry
                                .connect_http_with_protocol_plan(
                                    &cx,
                                    &subject,
                                    "native",
                                    1,
                                    plan.clone(),
                                    proxy_http_client_info(),
                                    ClientCapabilities::default()
                                )
                                .await
                                .unwrap_err()
                                .code,
                            McpErrorCode::RequestCancelled
                        );
                        assert_eq!(received.load(Ordering::Acquire), 0);
                        assert!(registry.live_http.is_empty());
                        cx.set_cancel_requested(false);
                    }
                    for attempt in 0..attempts {
                        let request_cx = if attempt == 0 { &opening_cx } else { &cx };
                        let mut opening = Box::pin(registry.connect_http_with_protocol_plan(
                            request_cx,
                            &subject,
                            "native",
                            1,
                            plan.clone(),
                            proxy_http_client_info(),
                            ClientCapabilities::default(),
                        ));
                        let deadline = Instant::now() + Duration::from_secs(10);
                        loop {
                            assert!(
                                std::future::poll_fn(|task_cx| Poll::Ready(
                                    opening.as_mut().poll(task_cx)
                                ))
                                .await
                                .is_pending(),
                                "connection must yield while peer withholds its reply"
                            );
                            if received.load(Ordering::Acquire) > attempt {
                                break;
                            }
                            assert!(Instant::now() < deadline, "connection reaches peer");
                            asupersync::runtime::yield_now().await;
                        }
                        if attempt == 0 && interrupted_opening {
                            if interrupt == 2 {
                                drop(opening);
                            } else {
                                let cancelling_cx = opening_cx.clone();
                                let clock = Arc::clone(&clock);
                                let mut sibling = siblings
                                    .spawn(move |_| async move {
                                        assert_eq!(thread::current().id(), worker);
                                        if interrupt == 3 {
                                            clock.advance(100_000_000);
                                        } else {
                                            cancelling_cx.set_cancel_requested(true);
                                        }
                                    })
                                    .unwrap();
                                assert_eq!(
                                    opening.await.unwrap_err().code,
                                    McpErrorCode::RequestCancelled
                                );
                                sibling.join(&siblings).await.unwrap();
                            }
                            assert!(
                                registry.live_http.is_empty(),
                                "interrupted establishment cannot publish a cache entry"
                            );
                            release.send(true).unwrap();
                            continue;
                        }
                        let release_reply = release.clone();
                        let mut sibling = siblings
                            .spawn(move |_| async move {
                                assert_eq!(thread::current().id(), worker);
                                release_reply.send(false).unwrap();
                            })
                            .unwrap();
                        let proxy = opening.await.unwrap();
                        sibling.join(&siblings).await.unwrap();
                        assert_eq!(
                            proxy.upstream_binding().unwrap().era(),
                            if legacy {
                                ProtocolEra::Legacy2024
                            } else {
                                ProtocolEra::Modern2026
                            }
                        );
                        assert_eq!(registry.live_http.len(), 1);
                        let cached = registry
                            .connect_http_with_protocol_plan(
                                &cx,
                                &subject,
                                "native",
                                1,
                                plan.clone(),
                                proxy_http_client_info(),
                                ClientCapabilities::default(),
                            )
                            .await
                            .unwrap();
                        assert!(
                            Arc::ptr_eq(&proxy.inner, &cached.inner),
                            "same identity reuses the admitted backend"
                        );
                        cx.set_cancel_requested(true);
                        assert_eq!(
                            registry
                                .connect_http_with_protocol_plan(
                                    &cx,
                                    &subject,
                                    "native",
                                    1,
                                    plan.clone(),
                                    proxy_http_client_info(),
                                    ClientCapabilities::default()
                                )
                                .await
                                .unwrap_err()
                                .code,
                            McpErrorCode::RequestCancelled
                        );
                        assert_eq!(
                            registry.live_http.len(),
                            1,
                            "cancelled cache lookup preserves existing state"
                        );
                        assert_eq!(received.load(Ordering::Acquire), attempts);
                        cx.set_cancel_requested(false);
                        let mut catalog = Box::pin(proxy.catalog_typed_with_cx(&catalog_cx));
                        let deadline = Instant::now() + Duration::from_secs(10);
                        loop {
                            let polled = std::future::poll_fn(|task_cx| {
                                Poll::Ready(catalog.as_mut().poll(task_cx))
                            })
                            .await;
                            assert!(
                                polled.is_pending(),
                                "catalog must yield before the peer reply: {polled:?}"
                            );
                            if received.load(Ordering::Acquire) > attempts {
                                break;
                            }
                            assert!(Instant::now() < deadline, "catalog request reaches peer");
                            asupersync::runtime::yield_now().await;
                        }
                        if interrupt >= 5 {
                            if interrupt == 6 {
                                drop(catalog);
                            } else {
                                let cancelling_cx = catalog_cx.clone();
                                let clock = Arc::clone(&clock);
                                let mut sibling = siblings
                                    .spawn(move |_| async move {
                                        assert_eq!(thread::current().id(), worker);
                                        if interrupt == 5 {
                                            clock.advance(100_000_000);
                                        } else {
                                            cancelling_cx.set_cancel_requested(true);
                                        }
                                    })
                                    .unwrap();
                                assert_eq!(
                                    catalog.await.unwrap_err().code,
                                    McpErrorCode::RequestCancelled
                                );
                                sibling.join(&siblings).await.unwrap();
                            }
                            assert_eq!(registry.live_http.len(), 1);
                            release.send(true).unwrap();
                            if legacy {
                                release.send(false).unwrap();
                            }
                            continue;
                        }
                        let release_catalog = release.clone();
                        let sibling_proxy = proxy.clone();
                        let mut sibling = siblings
                            .spawn(move |_| async move {
                                assert_eq!(thread::current().id(), worker);
                                assert!(
                                    sibling_proxy.inner.try_lock().is_ok(),
                                    "catalog does not hold route mutex across I/O"
                                );
                                release_catalog.send(false).unwrap();
                            })
                            .unwrap();
                        let catalog = catalog.await;
                        sibling.join(&siblings).await.unwrap();
                        if interrupt == 4 {
                            let error = catalog.unwrap_err();
                            assert_eq!(error.code, McpErrorCode::InvalidRequest);
                            assert!(error.message.contains("non-advancing cursor"));
                        } else {
                            let catalog = catalog.unwrap();
                            let names: Vec<_> = match &catalog.tools {
                                ProxyToolCatalog::Legacy(tools) => {
                                    tools.iter().map(|tool| tool.name.clone()).collect()
                                }
                                ProxyToolCatalog::Final(tools) => {
                                    assert_eq!(tools.cache_hints.len(), 2);
                                    assert_eq!(
                                        serde_json::to_value(&tools.cache_hints[1].ttl_ms).unwrap(),
                                        18
                                    );
                                    tools.iter().map(|tool| tool.name.clone()).collect()
                                }
                            };
                            assert_eq!(names, [format!("{subject}-0"), format!("{subject}-1")]);
                            assert_eq!(
                                catalog.era().unwrap(),
                                proxy.upstream_binding().unwrap().era()
                            );
                        }
                        assert_eq!(
                            registry.live_http.len(),
                            1,
                            "catalog refusal preserves the bound connection"
                        );
                        if legacy {
                            release.send(false).unwrap();
                        }
                    }
                })
                .unwrap();
            work.join(&root).await.unwrap();
        });
        peer.join().unwrap();
        assert!(runtime.shutdown_timeout(Duration::from_secs(2)));
    }

