    #[test]
    fn proxy_modern_sse_progress_callback_rejects_one_invalid_progress_value() {
        let baseline = r#"{"jsonrpc":"2.0","method":"notifications/progress","params":{"progressToken":"job-17","progress":1.20e+4,"total":12000.0}}"#;
        let JsonRpcMessage::Request(baseline_request) =
            decode_strict_jsonrpc_message(baseline.as_bytes(), 4096)
                .expect("baseline modern progress notification parses")
        else {
            panic!("baseline is a JSON-RPC notification");
        };
        let baseline_notification =
            decode_modern_server_notification(baseline.as_bytes(), &baseline_request)
                .expect("baseline final progress is admitted");

        let invalid = r#"{"jsonrpc":"2.0","method":"notifications/progress","params":{"progressToken":"job-17","progress":"-1","total":12000.0}}"#;
        let JsonRpcMessage::Request(invalid_request) =
            decode_strict_jsonrpc_message(invalid.as_bytes(), 4096)
                .expect("one-variable string progress notification parses as JSON-RPC")
        else {
            panic!("invalid progress fixture is a JSON-RPC notification");
        };
        let mut delivered = Vec::new();
        let error = forward_modern_progress_notification(
            invalid.as_bytes(),
            &invalid_request,
            &mut |params| delivered.push(params),
            None,
        )
        .expect_err("changing only progress from a number to a string must be rejected");
        assert_eq!(error.code, McpErrorCode::InvalidRequest);
        assert!(
            delivered.is_empty(),
            "a rejected modern progress frame must not reach the exact callback"
        );
        assert_eq!(
            baseline_notification
                .encode_wire()
                .expect("baseline notification re-encodes byte-exactly"),
            baseline,
            "the rejected frame cannot alter the admitted raw-parameter baseline"
        );
    }

    fn proxy_cancel_timer_rearm_probe(cancel: bool) {
        use std::future::Future;
        use std::sync::atomic::{AtomicUsize, Ordering};
        use std::task::{Context, Poll, Wake, Waker};

        struct WakeCount(AtomicUsize);
        impl Wake for WakeCount {
            fn wake(self: Arc<Self>) {
                self.0.fetch_add(1, Ordering::SeqCst);
            }

            fn wake_by_ref(self: &Arc<Self>) {
                self.0.fetch_add(1, Ordering::SeqCst);
            }
        }

        // An unrelated cancelled ambient context makes a real Sleep immediately
        // ready on every rearm, deterministically exercising the same lifecycle
        // as a scheduler delay spanning the replacement timer's deadline.
        let ambient = Cx::for_testing();
        ambient.set_cancel_requested(true);
        let _ambient = Cx::set_current(Some(ambient));
        let cx = Cx::for_testing();
        let cancellation = McpRequestCancellation::new();
        let polls = AtomicUsize::new(0);
        let operation = std::future::poll_fn(|_| {
            if polls.fetch_add(1, Ordering::SeqCst) < 3 {
                Poll::Pending
            } else {
                Poll::Ready(Ok(73))
            }
        });
        let mut wait = Box::pin(super::await_proxy_operation_with_cancellation_priority(
            &cx,
            &cancellation,
            operation,
            None,
            None,
        ));
        let wakes = Arc::new(WakeCount(AtomicUsize::new(0)));
        let waker = Waker::from(Arc::clone(&wakes));
        let mut task_cx = Context::from_waker(&waker);
        for turn in 1..=3 {
            assert!(wait.as_mut().poll(&mut task_cx).is_pending());
            assert_eq!(polls.load(Ordering::SeqCst), turn);
        }
        assert!(
            wakes.0.load(Ordering::SeqCst) >= 3,
            "an immediately-ready replacement timer cannot leave the request parked"
        );
        if cancel {
            assert!(cancellation.cancel());
        }
        let Poll::Ready(result) = wait.as_mut().poll(&mut task_cx) else {
            panic!("upstream completion or request cancellation must finish the wait");
        };
        if cancel {
            assert_eq!(result.unwrap_err().code, McpErrorCode::RequestCancelled);
            assert_eq!(
                polls.load(Ordering::SeqCst),
                3,
                "late upstream result untouched"
            );
        } else {
            assert_eq!(result.unwrap(), 73);
            assert_eq!(polls.load(Ordering::SeqCst), 4);
        }
        assert!(
            !cx.is_cancel_requested(),
            "the explicit caller Cx remains live"
        );
    }

